function APR.event:RegisterEvents()
    for tag, event in pairs(events) do
        local container = self.framePool[tag] or CreateFrame("Frame")
        container.tag = tag
        container.callback = self.functions[tag]

        -- Save container to framePool for later cleanup
        self.framePool[tag] = container

        if type(event) == "string" then
            APR:RegisterSupportedEvent(container, event, playerUnitEvents[event] and "player" or nil)
            container:SetScript("OnEvent", self.EventHandler)
        elseif type(event) == "table" then
            for _, e in ipairs(event) do
                APR:RegisterSupportedEvent(container, e, playerUnitEvents[e] and "player" or nil)
            end
            container:SetScript("OnEvent", self.EventHandler)
        end
    end
    self:ObserveStartupQuestState()
    if self.routeValidationResume or self.routeMaintenanceResume then self:ResumeRouteValidation() end
end--[[APR_DIAG]]; APR.event.RegisterEvents = APRTrace("APR-Core/core/Event.lua:123:APR.event:RegisterEvents#3", APR.event.RegisterEvents)--[[/APR_DIAG]]

function APR.event.EventHandler(self, event, ...)
    -- Retain the filter on clients/adapters without RegisterUnitEvent. Opaque
    -- payloads follow the existing conservative handling inside each callback.
    if playerUnitEvents[event] then
        local unit = ...
        if APRSecret:CanAccessValue(unit) and unit ~= "player" then return end
    end
    -- Discovery owns its frame; neither public queries nor private replies refresh quests.
    if self.tag == "party" and not partyPrefixes[(...)] then return end
    -- Public version traffic needs no quest/UI refresh, profiling or group scan.
    if self.tag == "party" and select(3, ...) == "CHANNEL" then
        APR.versionCheck:HandleSharedMessage(...)
        return
    end
    local profile = APR:GetSettingsProfile()
    if not profile or not profile.enableAddon then
        return
    end
    local profileStart = APR:StartPerformanceSample()
    local parentScope = APR.performanceScope
    if profileStart then APR.performanceScope = "Event." .. tostring(self.tag) .. ":" .. event end

    local isInstanceWithUI = APR:IsInstanceWithUI()
    if isInstanceWithUI ~= lastIsInstanceWithUI then
        APR:Debug("APR: Event - IsInstanceWithUI : ", isInstanceWithUI)
        APR:RefreshInstanceUIVisibility()
        lastIsInstanceWithUI = isInstanceWithUI
    end

    APR:MaybePromptInstanceUIPreference()

    if not isInstanceWithUI then
        local isInstance, instanceType = IsInInstance()
        if isInstance and (instanceType == "pvp" or instanceType == "arena") then
            APR.performanceScope = parentScope
            APR:FinishPerformanceSample(event, profileStart, nil, parentScope)
            return
        end
    end

    if self.callback and self.tag then
        APR:DebugEvent("Callback Event", event)
        -- update Local variables before calling the callback
        autoAccept = profile.autoAccept
        autoAcceptRoute = profile.autoAcceptQuestRoute
        step = APR:GetCurrentStep()

        APR.npcInteraction:Track(self.tag, event)

        local ok, errorMessage = --[[APR_DIAG]]APRPCall--[=[--[[/APR_DIAG]]pcall--[[APR_DIAG]]]=]--[[/APR_DIAG]](self.callback, event, ...)
        if not ok then geterrorhandler()(errorMessage) end
    else
        APR:DebugEvent("Unregister Event", event)
        self.callback = nil
        self:UnregisterEvent(event)
    end
    APR.performanceScope = parentScope
    APR:FinishPerformanceSample(event, profileStart, nil, parentScope)
end--[[APR_DIAG]]; APR.event.EventHandler = APRTrace("APR-Core/core/Event.lua:146:APR.event.EventHandler#4", APR.event.EventHandler)--[[/APR_DIAG]]

-- Cleanup function to properly unregister events and clear handlers
function APR.event:CleanupEvents()
    self:CancelRouteValidation(true)
    APR.npcInteraction:Clear()
    if APR.CancelAutocompleteQuest then APR:CancelAutocompleteQuest() end
    if self.bankRefreshTimer then self.bankRefreshTimer:Cancel(); self.bankRefreshTimer = nil end
    self.reputationGeneration = (self.reputationGeneration or 0) + 1
    if self.reputationUpdateTimer then self.reputationUpdateTimer:Cancel(); self.reputationUpdateTimer = nil end
    if self.reputationCommitTimer then self.reputationCommitTimer:Cancel(); self.reputationCommitTimer = nil end
    if self.reputationJob then APR.questOrderListSupport:CancelRender(self.reputationJob) end
    if self.stepRefreshTimer then
        self.stepRefreshTimer:Cancel()
        self.stepRefreshTimer = nil
    end
    if pendingWarModeTimer then
        pendingWarModeTimer:Cancel()
        pendingWarModeTimer = nil
    end
    if pendingZoneRoutingTimer then
        pendingZoneRoutingTimer:Cancel()
        pendingZoneRoutingTimer = nil
    end
    if pendingQuestDataTimer then
        pendingQuestDataTimer:Cancel()
        pendingQuestDataTimer = nil
    end
    APR:ResetQuestTitleRequests()
    for tag, container in pairs(self.framePool) do
        if container then
            -- Unregister all events for this container
            container:UnregisterAllEvents()
            -- Clear script handlers
            container:SetScript("OnEvent", nil)
            -- Clear references
            container.tag = nil
            container.callback = nil
        end
    end
    -- Clear the event timer if running
    if pendingQuestUpdateTimer then
        pendingQuestUpdateTimer:Cancel()
        pendingQuestUpdateTimer = nil
    end

    -- Clear quest share queue
    wipe(questShareQueue)
    wipe(questShareRetries)

    CancelAdventureMapRetries()
end--[[APR_DIAG]]; APR.event.CleanupEvents = APRTrace("APR-Core/core/Event.lua:207:APR.event:CleanupEvents#5", APR.event.CleanupEvents)--[[/APR_DIAG]]

