        APR._lastRouteZoneCheck = nil
        APR._lastRouteZoneResult = nil

        if IsInInstance() and not APR:IsInstanceWithUI() then
            if pendingZoneRoutingTimer then
                pendingZoneRoutingTimer:Cancel()
